2 --west\n    data.lpduP1ClockArrow=green:addTimedArrow(time, 100, 0, 100, heading, 17, 1, 1, 1,0,true)\nelseif index == 4 then --healer2\n    local heading = heading2North + math.pi --south\n    data.lpduP1ClockArrow=green:addTimedArrow(time, 100, 0, 100, heading, 17, 1, 1, 1,0,true)\nelseif index == 5 then --melee1\n    local heading = heading2North + math.pi/2 + math.pi/4 --southwest\n    data.lpduP1ClockArrow=green:addTimedArrow(time, 100, 0, 100, heading, 17, 1, 1, 1,0,true)\nelseif index == 6 then --melee2\n    local heading = heading2North - math.pi/2 - math.pi/4 --southeast\n    data.lpduP1ClockArrow=green:addTimedArrow(time, 100, 0, 100, heading, 17, 1, 1, 1,0,true)\nelseif index == 7 then --range1\n    local heading = heading2North + math.pi/4 --northwest\n    data.lpduP1ClockArrow=green:addTimedArrow(time, 100, 0, 100, heading, 17, 1, 1, 1,0,true)\nelseif index == 8 then --range2\n    local heading = heading2North - math.pi/4 --northeast\n    data.lpduP1ClockArrow=green:addTimedArrow(time, 100, 0, 100, heading, 17, 1, 1, 1,0,true)\nend\nself.used = true",
