							actionLua = "local function table_subtract(table1, table2)\n    local result = {}\n    local table2_set = {}\n\n    -- Convert table2 to a set for fast lookups\n    for _, value in ipairs(table2) do\n        table2_set[value] = true\n    end\n\n    -- Add elements from table1 that are not in table2\n    for _, value in ipairs(table1) do\n        if not table2_set[value] then\n            table.insert(result, value)\n        end\n    end\n\n    return result\nend\nlocal green = TensorCore.getStaticDrawer(GUI:ColorConvertFloat4ToU32(0/255, 255/255, 0/255, .25),2)\nlocal function followupArrow(...)\n if data.lpduP1ClockArrow then\n  Argus.deleteTimedShape(data.lpduP1ClockArrow)\n  data.lpduP1ClockArrow=nil\n end\n return green:addTimedArrow(...)\nend\nlocal p = TensorCore.mGetPlayer()\nlocal center = {x = 100, y = 0,z = 100}\nlocal index\nlocal heading2North = TensorCore.getHeadingToTarget(center,{x = 100, y = 0,z = 70})\n--party should be tank1 tank2 healer1 healer2 melee1 melee2 range1 range2\nlocal roster = AnyoneCore and AnyoneCore.Roster\r\nif roster == nil or roster.current() == nil then\r\n    self.used = true\r\n    return\r\nend\r\nlocal mySlot = roster.mySlot()\r\nlocal myRole = (mySlot == \"T1\" and \"MT\") or (mySlot == \"T2\" and \"OT\") or mySlot\r\nif not roster.isReady() then\r\n    self.used = true\r\n    return\r\nend\r\nif p == nil then self.used = true; return end\r\nif myRole == \"MT\" then index = 1\r\nelseif myRole == \"OT\" then index = 2\r\nelseif myRole == \"H1\" then index = 3\r\nelseif myRole == \"H2\" then index = 4\r\nelseif myRole == \"M1\" then index = 5\r\nelseif myRole == \"M2\" then index = 6\r\nelseif myRole == \"R1\" then index = 7\r\nelseif myRole == \"R2\" then index = 8\r\nelse self.used = true; return end\r\nif Settings.FFXIVMINION.LPDU_FRU_P1SwapRangedSpreads==\"Enabled\" and (data.megaminx_p1utopian_sky==1) then\n local swapIndex={[5]=7,[6]=8,[7]=5,[8]=6}\n index=swapIndex[index] or index\nend\nlocal partyIDs = {\r\n    roster.idOf(\"T1\"),\r\n    roster.idOf(\"T2\"),\r\n    roster.idOf(\"H1\"),\r\n    roster.idOf(\"H2\"),\r\n    roster.idOf(\"M1\"),\r\n    roster.idOf(\"M2\"),\r\n    roster.idOf(\"R1\"),\r\n    roster.idOf(\"R2\")\r\n}if data.megaminx_p1utopian_safe_clones == nil then data.megaminx_p1utopian_safe_clones = {} end\nif data.megaminx_p1utopian_unsafe_clones == nil then data.megaminx_p1utopian_unsafe_clones = {} end\nif eventArgs.newAnimID == 34 then\n    table.insert(data.megaminx_p1utopian_safe_clones,eventArgs.entityID)\nend\nif eventArgs.newAnimID == 210 then\n    table.insert(data.megaminx_p1utopian_unsafe_clones,eventArgs.entityID)\nend\nlocal max_distance = 0\nlocal opposite_positions = nil\nif table.size(data.megaminx_p1utopian_safe_clones) == 8 and table.size(data.megaminx_p1utopian_unsafe_clones) == 3 then\n    local unmarked = table_subtract(data.megaminx_p1utopian_safe_clones,data.megaminx_p1utopian_unsafe_clones)\n    for i = 1, #unmarked do\n        for j = i + 1, #unmarked do\n            local distance = TensorCore.getDistance2d(TensorCore.mGetEntity(unmarked[i]).pos, TensorCore.mGetEntity(unmarked[j]).pos)\n            if distance > max_distance then\n                max_distance = distance\n                opposite_positions = {unmarked[i], unmarked[j]}\n            end\n        end\n    end\nend\nif opposite_positions then\n    \n    local ent1 = TensorCore.mGetEntity(opposite_positions[1])\n    local ent2 = TensorCore.mGetEntity(opposite_positions[2])\n    if (ent1.pos.x < 105 and ent1.pos.x > 95) then --N S\n        if index == 1 then --tank1\n            local heading = heading2North\n            local origin = TensorCore.getPosInDirection(center,heading,19)\n            local pos = TensorCore.getPosInDirection(origin,heading+math.pi,6)\n            local finalHeading = TensorCore.getHeadingToTarget(center,pos)\n            local distance = TensorCore.getDistance2d(center,pos) - 1\n            if data.megaminx_p1utopian_sky == 0 then --stack\n                followupArrow(10000, 100, 0, 100, heading, 15, 1, 1, 1,0,true)\n            else\n                followupArrow(10000, 100, 0, 100, finalHeading, distance, 1, 1, 1,0,true)\r\n                local circlePos = pos\r\n                if index == 1 or index == 2 then\r\n                    circlePos = origin\r\n                end\r\n                green:addTimedCircle(10000, circlePos.x, 0, circlePos.z, 1, 0, true)\n            end\n        end\n        if index == 3 then --healer1\n            local heading = heading2North\n            local origin = TensorCore.getPosInDirection(center,heading,19)\n            local pos = TensorCore.getPosInDirection(origin,heading+math.pi,0)\n            local finalHeading = TensorCore.getHeadingToTarget(center,pos)\n            local distance = TensorCore.getDistance2d(center,pos) - 1\n            if data.megaminx_p1utopian_sky == 0 then --stack\n                followupArrow(10000, 100, 0, 100, heading, 15, 1, 1, 1,0,true)\n            else\n                followupArrow(10000, 100, 0, 100, finalHeading, distance, 1, 1, 1,0,true)\r\n                local circlePos = pos\r\n                if index == 1 or index == 2 then\r\n                    circlePos = origin\r\n                end\r\n                green:addTimedCircle(10000, circlePos.x, 0, circlePos.z, 1, 0, true)\n            end        end\n        if index == 5 then --melee1\n            local heading = heading2North\n            local origin = TensorCore.getPosInDirection(center,heading,19)\n            local pos = TensorCore.getPosInDirection(origin,heading+math.pi+math.pi/2,6)\n            local finalHeading = TensorCore.getHeadingToTarget(center,pos)\n            local distance = TensorCore.getDistance2d(center,pos) - 1\n            if data.megaminx_p1utopian_sky == 0 then --stack\n                followupArrow(10000, 100, 0, 100, heading, 15, 1, 1, 1,0,true)\n            else\n                followupArrow(10000, 100, 0, 100, finalHeading, distance, 1,