						data = 
						{
							aType = "Lua",
							actionLua = "local function stop()\n    self.used = true\nend\n\nif data.megaminx_p1flexstack == nil then\n    data.megaminx_p1flexstack = {}\nend\ntable.insert(data.megaminx_p1flexstack, {\n    tetherid = eventArgs.newTargetID,\n    sourceid = eventArgs.sourceEntityID\n})\n\nif #data.megaminx_p1flexstack ~= 2 then\n    stop()\n    return\nend\n\nlocal safeside\nif data.megaminx_p1stackflex == 0 and data.megaminx_p1stackflex_ew == 0 then\n    safeside = 0\nelseif data.megaminx_p1stackflex == 0 and data.megaminx_p1stackflex_ew == 1 then\n    safeside = 1\nelseif data.megaminx_p1stackflex == 1 and data.megaminx_p1stackflex_ew == 1 then\n    safeside = 0\nelseif data.megaminx_p1stackflex == 1 and data.megaminx_p1stackflex_ew == 0 then\n    safeside = 1\nend\nif safeside == nil then\n    stop()\n    return\nend\n\nlocal player = TensorCore.mGetPlayer()\nlocal roster = AnyoneCore and AnyoneCore.Roster\nif player == nil or player.id == nil or roster == nil\n    or roster.current == nil or roster.mySlot == nil\n    or roster.isReady == nil or roster.idOf == nil\n    or roster.current() == nil or not roster.isReady() then\n    stop()\n    return\nend\n\nlocal slots = { \"T1\", \"T2\", \"H1\", \"H2\", \"M1\", \"M2\", \"R1\", \"R2\" }\nlocal idToSlot = {}\nfor _, slot in ipairs(slots) do\n    local id = roster.idOf(slot)\n    if id ~= nil then\n        idToSlot[id] = slot\n    end\nend\n\nlocal preySlots = {}\nlocal preyCounts = { [1] = 0, [2] = 0 }\nfor _, tether in ipairs(data.megaminx_p1flexstack) do\n    local slot = idToSlot[tether.tetherid]\n    if slot == nil then\n        stop()\n        return\n    end\n    local group = (slot == \"T1\" or slot == \"H1\" or slot == \"M1\" or slot == \"R1\") and 1 or 2\n    preyCounts[group] = preyCounts[group] + 1\n    table.insert(preySlots, { slot = slot, group = group })\nend\n\nlocal mySlot = roster.mySlot()\nlocal myGroup\nif mySlot == \"T1\" or mySlot == \"H1\" or mySlot == \"M1\" or mySlot == \"R1\" then\n    myGroup = 1\nelseif mySlot == \"T2\" or mySlot == \"H2\" or mySlot == \"M2\" or mySlot == \"R2\" then\n    myGroup = 2\nelse\n    stop()\n    return\nend\n\n-- LPDU P1: G1 north, G2 south. For two preys in one group,\n-- T > M > R > H selects the prey swapping groups; the tank from\n-- the zero-prey group swaps the other way to keep the light parties even.\nlocal finalGroup = myGroup\nlocal doubledGroup\nif preyCounts[1] == 2 then\n    doubledGroup = 1\nelseif preyCounts[2] == 2 then\n    doubledGroup = 2\nend\nif doubledGroup ~= nil then\n    local priority = {\n        T1 = 1, T2 = 1,\n        M1 = 2, M2 = 2,\n        R1 = 3, R2 = 3,\n        H1 = 4, H2 = 4\n    }\n    local swapPrey\n    local bestPriority = math.huge\n    for _, prey in ipairs(preySlots) do\n        if prey.group == doubledGroup and priority[prey.slot] < bestPriority then\n            swapPrey = prey.slot\n            bestPriority = priority[prey.slot]\n        end\n    end\n    local zeroGroup = 3 - doubledGroup\n    local tankFromZeroGroup = \"T\" .. tostring(zeroGroup)\n    if mySlot == swapPrey then\n        finalGroup = zeroGroup\n    elseif mySlot == tankFromZeroGroup then\n        finalGroup = doubledGroup\n    end\nend\n\nlocal x = safeside == 0 and 95 or 105\nlocal z = finalGroup == 1 and 95 or 105\nlocal target = { x = x, y = 0, z = z }\nlocal center = { x = 100, y = 0, z = 100 }\n-- Match the legacy LPDU stack indicator geometry: the arrow runs from arena center to this player's assigned stack spot.\nlocal heading = TensorCore.getHeadingToTarget(center, target)\nlocal arrowLength = TensorCore.getDistance2d(center, target)\nif arrowLength <= 0.1 then\n    stop()\n    return\nend\n\nlocal green = TensorCore.getStaticDrawer(\n    GUI:ColorConvertFloat4ToU32(0 / 255, 255 / 255, 0 / 255, .45),\n    2\n)\n-- Own the large side-assignment arrow so the inward step can retire it.\nif data.lpduP1LargeSideArrow then Argus.deleteTimedShape(data.lpduP1LargeSideArrow) end\ndata.lpduP1LargeSideArrow = green:addTimedArrow(10000, center.x, center.y, center.z, heading, arrowLength, 2, 1.5, 3, 0, true)\n\nstop()",
