							actionLua = "local state = data.frup1_lpdu_four_tether\nif state == nil then\n    state = {\n        records = {},\n        positionByOrder = {[1] = 1, [2] = 2, [3] = 3, [4] = 4},\n        partnerByOrder = {[1] = 3, [3] = 1, [2] = 4, [4] = 2}\n    }\n    data.frup1_lpdu_four_tether = state\nend\nstate.records = state.records or {}\nstate.positionByOrder = state.positionByOrder or {[1] = 1, [2] = 2, [3] = 3, [4] = 4}\nstate.partnerByOrder = state.partnerByOrder or {[1] = 3, [3] = 1, [2] = 4, [4] = 2}\n-- Splatoon/LPDU spots: 1 north inner, 2 south inner, 3 north outer, 4 south outer.\n-- Reset each event so a live profile edit also updates existing encounter state.\nstate.tetherPositions = {\n    [1] = {x = 100, y = 0, z = 95},\n    [2] = {x = 100, y = 0, z = 105},\n    [3] = {x = 100, y = 0, z = 93},\n    [4] = {x = 100, y = 0, z = 107}\n}\n\nlocal records = state.records\nlocal positions = state.tetherPositions\nlocal isTetherAdd = (eventArgs.newTetherID == 249 or eventArgs.newTetherID == 287)\n    and eventArgs.newTargetID ~= nil\nlocal isTetherClear = eventArgs.newTetherID == 0\n    -- Lightning is initially 287 but can clear as 31 -> 0 (pull9 evidence).\n    and (eventArgs.oldTetherID == 249 or eventArgs.oldTetherID == 287 or eventArgs.oldTetherID == 31)\n    and eventArgs.oldTargetID ~= nil\nlocal swapFrom = nil\nlocal swapTo = nil\nlocal swapTether = nil\n\nif isTetherAdd then\n    local record = nil\n    for _, existing in ipairs(records) do\n        if existing.id == eventArgs.newTargetID then\n            record = existing\n            break\n        end\n    end\n\n    if record ~= nil then\n        record.tether = eventArgs.newTetherID\n    elseif #records < 4 then\n        table.insert(records, {\n            id = eventArgs.newTargetID,\n            tether = eventArgs.newTetherID,\n            order = #records + 1,\n            resolved = false\n        })\n    end\nend\n\nif isTetherClear then\n    for _, record in ipairs(records) do\n        if record.id == eventArgs.oldTargetID\n            and (record.tether == eventArgs.oldTetherID\n                or (record.tether == 287 and eventArgs.oldTetherID == 31))\n            and not record.resolved then\n            record.resolved = true\n            if record.order == 1 and not state.swapped13 then\n                local nextTether = records[3]\n                if nextTether ~= nil and not nextTether.resolved then\n                    swapFrom = positions[state.positionByOrder[3] or 3]\n                    swapTether = nextTether.tether\n                end\n                state.positionByOrder[1], state.positionByOrder[3] =\n                    state.positionByOrder[3], state.positionByOrder[1]\n                if swapFrom ~= nil then\n                    swapTo = positions[state.positionByOrder[3] or 3]\n                end\n                state.swapped13 = true\n            elseif record.order == 2 and not state.swapped24 then\n                local nextTether = records[4]\n                if nextTether ~= nil and not nextTether.resolved then\n                    swapFrom = positions[state.positionByOrder[4] or 4]\n                    swapTether = nextTether.tether\n                end\n                state.positionByOrder[2], state.positionByOrder[4] =\n                    state.positionByOrder[4], state.positionByOrder[2]\n                if swapFrom ~= nil then\n                    swapTo = positions[state.positionByOrder[4] or 4]\n                end\n                state.swapped24 = true\n            end\n            break\n        end\n    end\nend\n\nlocal player = TensorCore.mGetPlayer()\n-- Retire the initial LPDU conga arrow when the tether assignment takes over.\nlocal setupArrow = data.frup1_lpdu_conga_setup\nif type(setupArrow) == \"table\" and setupArrow.arrowUUID ~= nil\n    and ((isTetherAdd and player ~= nil and eventArgs.newTargetID == player.id)\n        or #records >= 4) then\n    Argus.deleteTimedShape(setupArrow.arrowUUID)\n    setupArrow.arrowUUID = nil\n    if setupArrow.circleUUID ~= nil then\n        Argus.deleteTimedShape(setupArrow.circleUUID)\n        setupArrow.circleUUID = nil\n    end\nend\nlocal center = {x = 100, y = 0, z = 100}\n-- Red marks fire/stack; blue marks lightning/spread.\nlocal stackRed = TensorCore.getStaticDrawer(\n    GUI:ColorConvertFloat4ToU32(1, .16, .12, .55), 2)\nlocal spreadBlue = TensorCore.getStaticDrawer(\n    GUI:ColorConvertFloat4ToU32(.10, .52, 1, .55), 2)\nlocal green = TensorCore.getStaticDrawer(\n    GUI:ColorConvertFloat4ToU32(0/255, 255/255, 0/255, .25), 2)\nlocal markerRadius = 1.0\n-- Never extend a Fall of Faith marker beyond timeline 118.\nlocal markerTimeout = math.min(15000, math.max(0, math.floor((118 - TensorReactions_CurrentTimer) * 1000)))\n\n-- Personal circle only during the local player's active tether bait turn.\n-- Waiting prey and other players' circles stay hidden; second prey takes over after clear.\nfor order, record in ipairs(records) do\n    local firstOrder = (order == 1 or order == 3) and 1 or 2\n    local secondOrder = firstOrder == 1 and 3 or 4\n    local firstRecord = records[firstOrder]\n    local activeOrder = nil\n    if firstRecord ~= nil and not firstRecord.resolved then\n        activeOrder = firstOrder\n    elseif firstRecord ~= nil and firstRecord.resolved then\n        local secondRecord = records[secondOrder]\n        if secondRecord ~= nil and not secondRecord.resolved then\n            activeOrder = secondOrder\n        end\n    end\n\n    local isActiveBait = order == activeOrder\n    local position = positions[state.positionByOrder[order] or order]\n    local isStack = record.tether == 249\n    local drawer = isStack and stackRed or spreadBlue\n\n    if isActiveBait and player ~= nil and record.id == player.id and position ~= nil then\n        if record.markerUUID ~= nil then\n            local updated = drawer:updateTimedCircle(\n                record.markerUUID, markerTimeout, position.x, position.y, position.z,\n                markerRadius, 0, true, false)\n            if not updated then\n                Argus.deleteTimedShape(record.markerUUID)\n                record.markerUUID = nil\n            end\n        end\n        if record.markerUUID == nil then\n            record.markerUUID = drawer:addTimedCircle(\n                markerTimeout, position.x, position.y, position.z, markerRadius, 0, true)\n        end\n    elseif record.markerUUID ~= nil then\n        Argus.deleteTimedShape(record.markerUUID)\n        record.markerUUID = nil\n    end\nend\n\nlocal targetPosition = nil\nlocal myRecord = nil\nif player ~= nil then\n    for _, record in ipairs(records) do\n        if record.id == player.id then\n            myRecord = record\n            break\n        end\n    end\nend\n\n-- The tethered player follows their own prey order and swap.\nif myRecord ~= nil and not myRecord.resolved then\n    targetPosition = positions[state.positionByOrder[myRecord.order] or myRecord.order]\nelseif #records >= 4 and player ~= nil then\n    -- LPDU conga priority: H1, H2, MT, OT, M1, M2, R1, R2.\n    -- Among non-tethered players, the first two go north and the next two south.\n    local anyTetherUnresolved = false\n    local tethered = {}\n    for _, record in ipairs(records) do\n        if not record.resolved then anyTetherUnresolved = true end\n        tethered[record.id] = true\n    end\n\n    local roster = AnyoneCore and AnyoneCore.Roster\n    if anyTetherUnresolved and roster ~= nil and roster.current() ~= nil\n        and roster.isReady() then\n        local slotOrder = {\"H1\", \"H2\", \"T1\", \"T2\", \"M1\", \"M2\", \"R1\", \"R2\"}\n        local fillers = {}\n        for _, slot in ipairs(slotOrder) do\n            local id = roster.idOf(slot)\n            if id ~= nil and not tethered[id] then\n                table.insert(fillers, slot)\n            end\n        end\n\n        local mySlot = roster.mySlot()\n        if #fillers == 4 and mySlot ~= nil then\n            for i, slot in ipairs(fillers) do\n                if slot == mySlot then\n                    targetPosition = i <= 2\n                        and {x = 100, y = 0, z = 92}\n                        or {x = 100, y = 0, z = 108}\n                    break\n                end\n            end\n        end\n    end\nend\n\n\n-- Recreate the local guidance arrow after circles so it renders above them.\nif state.localArrowUUID ~= nil then\n    Argus.deleteTimedShape(state.localArrowUUID)\n    state.localArrowUUID = nil\nend\n-- Personal helper guidance owns its arrow until its own hit resolves.\nlocal helperGuide = data.lpduFruFofHelperGuide\nif helperGuide and helperGuide.arrow then targetPosition = nil end\nif targetPosition ~= nil then\n    local heading = TensorCore.getHeadingToTarget(center, targetPosition)\n    local distance = TensorCore.getDistance2d(center, targetPosition) - 1\n    state.localArrowUUID = green:addTimedArrow(\n        5000, center.x, center.y, center.z, heading,\n        distance, 1, 1, 1, 0, true)\nend\n\nself.used = true",
