							actionLua = "local function finish()\n    self.used = true\nend\n\nlocal roster = AnyoneCore and AnyoneCore.Roster\nif roster == nil or roster.current == nil or roster.mySlot == nil\n    or roster.isReady == nil or roster.current() == nil or not roster.isReady() then\n    return\nend\n\nlocal roleOrder = {\"H1\", \"H2\", \"T1\", \"T2\", \"M1\", \"M2\", \"R1\", \"R2\"}\nlocal mySlot = roster.mySlot()\nlocal slotIndex = nil\nfor index, slot in ipairs(roleOrder) do\n    if slot == mySlot then\n        slotIndex = index\n        break\n    end\nend\nif slotIndex == nil then\n    return\nend\n\nlocal player = TensorCore.mGetPlayer()\nif player == nil or player.pos == nil then\n    return\nend\n\n-- LPDU north-to-south order; west-side lineup anchored to pre-tether debug positions.\n-- H1/H2 and melee anchors observed; remaining slots keep the same ordered spacing.\nlocal lineupZ = {91.3, 94.3, 97.1, 99.3, 101.5, 103.7, 105.9, 108.1}\nlocal target = {\n    x = 94,\n    y = player.pos.y or 0,\n    z = lineupZ[slotIndex]\n}\n-- Fixed arena-center origin avoids tiny/hidden arrows when already near the spot.\nlocal start={x=100,y=target.y,z=100}\nlocal drawer=TensorCore.getStaticDrawer(GUI:ColorConvertFloat4ToU32(0,1,0,.35),2)\nlocal state=data.frup1_lpdu_conga_setup or {}\ndata.frup1_lpdu_conga_setup=state\nlocal timeout=math.max(1,math.floor((101-TensorReactions_CurrentTimer)*1000))\nstate.circleUUID=drawer:addTimedCircle(timeout,target.x,target.y+.05,target.z,.65,0,true,true)\nlocal distance=TensorCore.getDistance2d(start,target)\nstate.arrowUUID=drawer:addTimedArrow(timeout,start.x,start.y+.05,start.z,TensorCore.getHeadingToTarget(start,target),math.max(.1,distance-.8),.7,.8,1.4,0,true)\n\nfinish()",
