							actionLua = "local state=data.frup1_lpdu_four_tether\nif not state or not state.records or #state.records<4 then self.used=true;return end\nlocal own=data.lpduFruFofHelperGuide\nif not own then own={};data.lpduFruFofHelperGuide=own end\nlocal function clear()\n if own.circle then Argus.deleteTimedShape(own.circle);own.circle=nil end\n if own.arrow then Argus.deleteTimedShape(own.arrow);own.arrow=nil end\nend\nlocal roster=AnyoneCore and AnyoneCore.Roster\nif not roster or roster.current()==nil or not roster.isReady() then clear();self.used=true;return end\nlocal p=TensorCore.mGetPlayer()\nif not p or not p.pos then clear();self.used=true;return end\nlocal records=state.records\nlocal myOrder\nlocal tethered={}\nfor order,record in ipairs(records) do\n tethered[record.id]=true\n if record.id==p.id then myOrder=order end\nend\nlocal slotOrder={\"H1\",\"H2\",\"T1\",\"T2\",\"M1\",\"M2\",\"R1\",\"R2\"}\nlocal fillers={}\nfor _,slot in ipairs(slotOrder) do\n local id=roster.idOf(slot)\n if not id then clear();self.used=true;return end\n if not tethered[id] then fillers[#fillers+1]=id end\nend\nif #fillers~=4 then clear();self.used=true;return end\nlocal side,helper\nif myOrder then\n side=(myOrder==1 or myOrder==3) and 1 or 2\n helper=\"middle\"\nelse\n for index,id in ipairs(fillers) do\n  if id==p.id then\n   side=index<=2 and 1 or 2\n   helper=(index==1 or index==3) and \"left\" or \"right\"\n   break\n  end\n end\nend\nif not side then clear();self.used=true;return end\nlocal first=side\nlocal second=side+2\nlocal active=not records[first].helperResolved and first or (not records[second].helperResolved and second or nil)\n-- Active bait keeps the existing tether-pass arrow and its personal circle.\nif not active or myOrder==active then clear();self.used=true;return end\nlocal record=records[active]\n-- LPDU active bait is the inner north/south spot. Keep each formation fixed.\nlocal anchor={pos=state.tetherPositions and state.tetherPositions[side]}\nif not anchor.pos then clear();self.used=true;return end\nlocal fx,fz=100-anchor.pos.x,100-anchor.pos.z\nlocal length=math.sqrt(fx*fx+fz*fz)\nif length<2 then clear();self.used=true;return end\nfx,fz=fx/length,fz/length\n-- Looking from the tether player toward arena-center boss: left is (fz,-fx).\nlocal leftX,leftZ=fz,-fx\nlocal lateral=helper==\"left\" and 1 or (helper==\"right\" and -1 or 0)\nlocal fire=record.tether==249\nlocal back,across\nif fire then\n back=2.2;across=lateral*.65\nelseif helper==\"middle\" then\n back=3;across=0\nelse\n back=0;across=lateral*3\nend\nlocal target={x=anchor.pos.x-fx*back+leftX*across,y=p.pos.y,z=anchor.pos.z-fz*back+leftZ*across}\n-- Call once per personal side sequence, independent of opposite-side resolution.\nlocal key=tostring(active)..\":\"..tostring(record.tether)..\":\"..helper\n-- Retire the generic helper arrow before returning for an unchanged assignment.\nif state.localArrowUUID then Argus.deleteTimedShape(state.localArrowUUID);state.localArrowUUID=nil end\nif own.key==key then self.used=true;return end\nclear();own.key=key\nlocal text=fire and \"Next: stack behind tether\" or (\"Lightning \"..helper)\nAnyoneCore.Shotcall(text,true,2.5,true)\n-- One persistent draw per personal step; the hit event advances this side only.\nlocal timeout=math.max(1,math.floor((118-TensorReactions_CurrentTimer)*1000))\nlocal color=fire and GUI:ColorConvertFloat4ToU32(1,.16,.12,.55) or GUI:ColorConvertFloat4ToU32(.10,.52,1,.55)\nlocal drawer=TensorCore.getStaticDrawer(color,2)\nown.circle=drawer:addTimedCircle(timeout,target.x,target.y+.05,target.z,.65,0,true,true)\nlocal origin={x=100,y=p.pos.y+.05,z=100}\nlocal distance=TensorCore.getDistance2d(origin,target)\nif distance>.5 then\n local green=TensorCore.getStaticDrawer(GUI:ColorConvertFloat4ToU32(0,1,0,.75),2)\n local heading=TensorCore.getHeadingToTarget(origin,target)\n local tip=math.min(.8,distance)\n own.arrow=green:addTimedArrow(timeout,origin.x,origin.y,origin.z,heading,math.max(.1,distance-tip),.55,tip,1.2,0,true)\nend\nself.used=true\n",
