						data = 
						{
							aType = "Lua",
							actionLua = "local function stop()\n    self.used = true\nend\n\nlocal roster = AnyoneCore and AnyoneCore.Roster\nif roster == nil or roster.current == nil or roster.current() == nil\n    or roster.mySlot == nil or roster.isReady == nil or not roster.isReady() then\n    stop()\n    return\nend\n\nlocal mySlot = roster.mySlot()\nif mySlot ~= \"T1\" and mySlot ~= \"T2\" then\n    stop()\n    return\nend\n\nlocal player = TensorCore.mGetPlayer()\nif player == nil or player.pos == nil then\n    stop()\n    return\nend\n\nlocal towers = data.megaminx_p1_3stacktower\nif type(towers) ~= \"table\" or #towers < 3 then\n    stop()\n    return\nend\n\nlocal totalX = 0\nlocal count = 0\nfor _, tower in ipairs(towers) do\n    if tower ~= nil and tower.id ~= nil then\n        local entity = TensorCore.mGetEntity(tower.id)\n        if entity ~= nil and entity.pos ~= nil then\n            totalX = totalX + entity.pos.x\n            count = count + 1\n        end\n    end\nend\nif count == 0 then\n    stop()\n    return\nend\n\n-- Tanks solve Powdermark opposite the tower side.\nlocal towersEast = (totalX / count) > 100\nlocal safeX = towersEast and 84 or 116\nlocal safePos = { x = safeX, y = 0, z = 100 }\nlocal outsidePos = { x = towersEast and 94 or 106, y = 0, z = 100 }\nlocal playerPos = { x = player.pos.x, y = player.pos.y or 0, z = player.pos.z }\nlocal center = { x = 100, y = 0, z = 100 }\n\nlocal drawer = TensorCore.getStaticDrawer(GUI:ColorConvertFloat4ToU32(0/255, 255/255, 0/255, .25), 2)\n\n-- Stay outside the first Burnt Strike hit.\nlocal outHeading = TensorCore.getHeadingToTarget(playerPos, outsidePos)\nlocal outDistance = TensorCore.getDistance2d(playerPos, outsidePos) - 1\nif outDistance > 0 then\n    drawer:addTimedArrow(6200, playerPos.x, playerPos.y, playerPos.z, outHeading, outDistance, 1, 1, 1, 0, true)\nend\n\n-- After the first hit, walk inward for the knockback and follow-up hits.\nlocal inHeading = TensorCore.getHeadingToTarget(safePos, center)\nlocal inDistance = TensorCore.getDistance2d(safePos, center) - 1\nif inDistance > 0 then\n    drawer:addTimedArrow(4700, safePos.x, safePos.y, safePos.z, inHeading, inDistance, 1, 1, 1, 6200, true)\nend\n\nstop()",
