					{
						data = 
						{
							aType = "Lua",
							actionLua = "if data.megaminx_p1_3stacktower == nil then data.megaminx_p1_3stacktower = {} end\ntable.insert(data.megaminx_p1_3stacktower,{spell = eventArgs.spellID, id = eventArgs.entityID, expires = Now() + eventArgs.channelTimeMax * 1000 })\nif table.size(data.megaminx_p1_3stacktower) == 3 then\n    local p = TensorCore.mGetPlayer()\n    local center = {x = 100, y = 0,z = 100}\n    local green = TensorCore.getStaticDrawer(GUI:ColorConvertFloat4ToU32(0/255, 255/255, 0/255, .25),2)\n    local index\n    local roster = AnyoneCore and AnyoneCore.Roster\r\n    if roster == nil or roster.current() == nil then\r\n        self.used = true\r\n        return\r\n    end\r\n    local mySlot = roster.mySlot()\r\n    local myRole = (mySlot == \"T1\" and \"MT\") or (mySlot == \"T2\" and \"OT\") or mySlot\r\n    if not roster.isReady() then\r\n        self.used = true\r\n        return\r\n    end\r\n    if p == nil then self.used = true; return end\r\n    if myRole == \"MT\" then index = 1\r\n    elseif myRole == \"OT\" then index = 2\r\n    elseif myRole == \"H1\" then index = 3\r\n    elseif myRole == \"H2\" then index = 4\r\n    elseif myRole == \"M1\" then index = 5\r\n    elseif myRole == \"M2\" then index = 6\r\n    elseif myRole == \"R1\" then index = 7\r\n    elseif myRole == \"R2\" then index = 8\r\n    else self.used = true; return end\r\n    local partyIDs = {\r\n        roster.idOf(\"T1\"),\r\n        roster.idOf(\"T2\"),\r\n        roster.idOf(\"H1\"),\r\n        roster.idOf(\"H2\"),\r\n        roster.idOf(\"M1\"),\r\n        roster.idOf(\"M2\"),\r\n        roster.idOf(\"R1\"),\r\n        roster.idOf(\"R2\")\r\n    }    if index == 3 then --healer1, go north\n        local ent = TensorCore.mGetEntity(eventArgs.entityID)\n        local pos\n        if ent.pos.x < 100 then\n            pos = {x = 87, y = 0, z = 90} --nw\n        elseif ent.pos.x > 100 then\n            pos = {x = 113, y = 0, z = 90} --ne\n        end\n        local heading = TensorCore.getHeadingToTarget(center,pos)\n        local distance = TensorCore.getDistance2d(center,pos) - 1\n        green:addTimedArrow(10000, 100, 0, 100, heading, distance, 1, 1, 1,0,true)\n    end\n    if index == 4 then --healer2, go sorth\n        local ent = TensorCore.mGetEntity(eventArgs.entityID)\n        local pos\n        if ent.pos.x < 100 then\n            pos = {x = 87, y = 0, z = 110} --nw\n        elseif ent.pos.x > 100 then\n            pos = {x = 113, y = 0, z = 110} --ne\n        end\n        local heading = TensorCore.getHeadingToTarget(center,pos)\n        local distance = TensorCore.getDistance2d(center,pos) - 1\n        green:addTimedArrow(10000, 100, 0, 100, heading, distance, 1, 1, 1,0,true)\n    end\n    if index == 8 then --range2(caster), go mid\n        local ent = TensorCore.mGetEntity(eventArgs.entityID)\n        local pos\n        if ent.pos.x < 100 then\n            pos = {x = 84, y = 0, z = 100} --w\n        elseif ent.pos.x > 100 then\n            pos = {x = 116, y = 0, z = 100} --e\n        end\n        local heading = TensorCore.getHeadingToTarget(center,pos)\n        local distance = TensorCore.getDistance2d(center,pos) - 1\n        green:addTimedArrow(10000, 100, 0, 100, heading, distance, 1, 1, 1,0,true)\n    end\n    local newTable = data.megaminx_p1_3stacktower\n\n    table.sort(newTable, function(a, b)\n        local entA = TensorCore.mGetEntity(a.id)\n        local entB = TensorCore.mGetEntity(b.id)\n        return entA.pos.z < entB.pos.z\n    end)\n\n    local spellToBase = {\n        [40124] = 4, [40127] = 4,\n        [40123] = 3, [40126] = 3,\n        [40122] = 2, [40125] = 2,\n        [40131] = 1, [40135] = 1\n    }\n    local function generateBaseTable(megaminxTable)\n        local baseTable = {}\n        for _, entry in ipairs(megaminxTable) do\n            if spellToBase[entry.spell] then\n                table.insert(baseTable, spellToBase[entry.spell])\n            end\n        end\n        return baseTable\n    end\n    local baseTable = generateBaseTable(newTable)\n    local adjustedTasks = {}\n    for i, task in ipairs(baseTable) do\n        adjustedTasks[i] = math.max(0, task - 1)\n    end\n    d(adjustedTasks)\n    local persons = {5, 7, 6} \n    local allocations = {0, 0, 0} \n\n    local function assignTasks(adjustedTasks, persons)\n        local taskAssignments = {} -- To store {id, task} pairs\n        local personIndex = 1      -- Start with the first person\n    \n        for taskIndex, taskCount in ipairs(adjustedTasks) do\n            local remaining = taskCount\n            \n            while remaining > 0 do\n                -- Assign one unit of the task to the current person\n                local personID = persons[personIndex]\n                table.insert(taskAssignments, {index = personID, task = taskIndex})\n                \n                -- Decrement the remaining count\n                remaining = remaining - 1\n                \n                -- Move to the next person in a round-robin fashion\n                personIndex = (personIndex % #persons) + 1\n            end\n        end\n    \n        return taskAssignments\n    end\n\n    local taskAssignments = assignTasks(adjustedTasks, persons)\n    local assigned = index == 3 and 1 or index == 4 and 3 or index == 8 and 2 or nil\n    if not assigned then\n        for _, assignment in ipairs(taskAssignments) do\n            if assignment.index == index then assigned = assignment.task; break end\n        end\n    end\n    if assigned and newTable[assigned] then\n        data.frup1_lpdu_tower_countdown = {\n            entityID = newTable[assigned].id,\n            expires = newTable[assigned].expires\n        }\n    end\n    d(taskAssignments)\n    for i = 1,#taskAssignments do\n        if index == taskAssignments[i].index then\n            if taskAssignments[i].task == 1 then -- north\n                local ent = TensorCore.mGetEntity(eventArgs.entityID)\n                local pos\n                if ent.pos.x < 100 then\n                    pos = {x = 87, y = 0, z = 90} --nw\n                elseif ent.pos.x > 100 then\n                    pos = {x = 113, y = 0, z = 90} --ne\n                end\n                local heading = TensorCore.getHeadingToTarget(center,pos)\n                local distance = TensorCore.getDistance2d(center,pos) - 1\n                green:addTimedArrow(10000, 100, 0, 100, heading, distance, 1, 1, 1,0,true)\n            end\n            if taskAssignments[i].task == 2 then -- mid\n                local ent = TensorCore.mGetEntity(eventArgs.entityID)\n                local pos\n                if ent.pos.x < 100 then\n                    pos = {x = 84, y = 0, z = 100} --w\n                elseif ent.pos.x > 100 then\n                    pos = {x = 116, y = 0, z = 100} --e\n                end\n                local heading = TensorCore.getHeadingToTarget(center,pos)\n                local distance = TensorCore.getDistance2d(center,pos) - 1\n                green:addTimedArrow(10000, 100, 0, 100, heading, distance, 1, 1, 1,0,true)\n            end\n            if taskAssignments[i].task == 3 then -- south\n                local ent = TensorCore.mGetEntity(eventArgs.entityID)\n                local pos\n                if ent.pos.x < 100 then\n                    pos = {x = 87, y = 0, z = 110} --nw\n                elseif ent.pos.x > 100 then\n                    pos = {x = 113, y = 0, z = 110} --ne\n                end\n                local heading = TensorCore.getHeadingToTarget(center,pos)\n                local distance = TensorCore.getDistance2d(center,pos) - 1\n                green:addTimedArrow(10000, 100, 0, 100, heading, distance, 1, 1, 1,0,true)\n            end\n        end\n    end\nend\n\nself.used = true\n",
