							actionLua = "local a=eventArgs;local e=TensorCore.mGetEntity(a.entityID)\nif not e or not e.pos then return end\nlocal old=data.lpdu_fru_ice_slide\nif old and old.boss==a.entityID and old.started==TensorReactions_CurrentTimer then self.used=true;return end\nif old then for _,id in ipairs(old.shapes) do Argus.deleteTimedShape(id) end end\nlocal s={boss=a.entityID,first=a.spellID,heading=e.pos.h,origin={x=e.pos.x,y=e.pos.y,z=e.pos.z},shapes={},started=TensorReactions_CurrentTimer}\ndata.lpdu_fru_ice_slide=s\nlocal heading=(s.heading+(s.first==40193 and math.pi or 0))%(2*math.pi)\nlocal p=TensorCore.mGetPlayer();if not p or not p.pos then return end\nlocal center={x=100,y=0,z=100}\nlocal radial=TensorCore.getHeadingToTarget(center,p.pos)\nlocal x,y,z=TensorCore.getPosInDirection(center,radial,17,true)\n-- Keep the occupied edge angle when safe; otherwise use the safe boss axis.\nlocal toPoint=TensorCore.getHeadingToTarget(s.origin,{x=x,y=y,z=z})\nlocal delta=math.abs((toPoint-heading+math.pi)%(2*math.pi)-math.pi)\nlocal half=s.first==40194 and 3*math.pi/4 or math.pi/4\nif delta>half-.08 then s.needsSetup=true end\ns.staging={x=x,y=y,z=z}\n-- A full ice slide is 32 yalms. Record a legal endpoint for the opposite cleave.\nlocal secondHeading=(s.heading+(s.first==40194 and math.pi or 0))%(2*math.pi)\nlocal secondHalf=s.first==40194 and math.pi/4 or 3*math.pi/4\nlocal best,score\nfor i=0,359 do\n local tx,ty,tz=TensorCore.getPosInDirection(s.staging,i*math.pi/180,32,true)\n local endPos={x=tx,y=ty,z=tz}\n local angle=TensorCore.getHeadingToTarget(s.origin,endPos)\n local diff=math.abs((angle-secondHeading+math.pi)%(2*math.pi)-math.pi)\n if (tx-100)^2+(tz-100)^2<18.5^2 and diff<secondHalf-.08 then\n  local value=(tx-100)^2+(tz-100)^2+20*diff\n  if not score or value<score then best=endPos;score=value end\n end\nend\nif not best or s.needsSetup then\n best=nil;score=nil\n local setup,setupScore\n for i=0,359 do\n  local tx,ty,tz=TensorCore.getPosInDirection(p.pos,i*math.pi/180,32,true)\n  local candidate={x=tx,y=ty,z=tz}\n  local angle=TensorCore.getHeadingToTarget(s.origin,candidate)\n  local diff=math.abs((angle-heading+math.pi)%(2*math.pi)-math.pi)\n  if (tx-100)^2+(tz-100)^2<18.5^2 and diff<half-.08 then\n   local value=(tx-s.origin.x)^2+(tz-s.origin.z)^2\n   if not setupScore or value>setupScore then setup=candidate;setupScore=value end\n  end\n end\n if setup then\n  s.staging=setup;x,y,z=setup.x,setup.y,setup.z\n  for i=0,359 do\n   local tx,ty,tz=TensorCore.getPosInDirection(setup,i*math.pi/180,32,true)\n   local candidate={x=tx,y=ty,z=tz}\n   local angle=TensorCore.getHeadingToTarget(s.origin,candidate)\n   local diff=math.abs((angle-secondHeading+math.pi)%(2*math.pi)-math.pi)\n   if (tx-100)^2+(tz-100)^2<18.5^2 and diff<secondHalf-.08 then\n    local value=(tx-100)^2+(tz-100)^2+20*diff\n    if not score or value<score then best=candidate;score=value end\n   end\n  end\n  s.adjust=true\n end\nend\ns.destination=best\nlocal d=TensorCore.getStaticDrawer(GUI:ColorConvertFloat4ToU32(0,1,0,.55),2,1)\nif s.adjust then\n local length=TensorCore.getDistance2d(p.pos,s.staging)\n local id=d:addTimedArrow(math.floor(a.channelTimeMax*1000),p.pos.x,p.pos.y+.05,p.pos.z,TensorCore.getHeadingToTarget(p.pos,s.staging),length-1,.9,1,2,0,false)\n if id then table.insert(s.shapes,id) end\nend\nlocal id=d:addTimedCircle(math.floor(a.channelTimeMax*1000+500),x,y+.05,z,1.2,0,true)\nif id then table.insert(s.shapes,id) end\nlocal currentHeading=TensorCore.getHeadingToTarget(s.origin,p.pos)\nlocal currentDelta=math.abs((currentHeading-heading+math.pi)%(2*math.pi)-math.pi)\nlocal needMove=s.adjust or currentDelta>half-.08\nAnyoneCore.Shotcall(needMove and \"Move\" or \"Wait\",true,3.2,false)\nself.used=true",
