  if boss == nil or boss.pos == nil then return end\n    base = boss.pos\n    offset = geometry.bossOffsets[spreadSlot]\nelse\n    base = TensorCore.getPosInDirection(center, heading, 20)\n    offset = geometry.mirrorOffsets[spreadSlot]\nend\nif offset == nil then self.used = true; return end\nlocal targetX = base.x + radialX * offset[1] + tangentX * offset[2]\nlocal targetZ = base.z + radialZ * offset[1] + tangentZ * offset[2]\nlocal duration = math.floor(a.channelTimeMax * 1000 + 850)\nlocal green = TensorCore.getStaticDrawer(GUI:ColorConvertFloat4ToU32(0, 1, 0, .92), 2)\ngreen:addTimedCircle3D(duration, targetX, .05, targetZ, 0.68677875, 0, 0, 0, false, true, Argus2.RenderFlags.FLAG_RENDER_UI)\nlocal player = TensorCore.mGetPlayer()\nif player ~= nil and player.pos ~= nil then\n    local target = { x = targetX, y = 0, z = targetZ }\n    local arrowHeading = TensorCore.getHeadingToTarget(player.pos, target)\n    local distance = TensorCore.getDistance2d(player.pos, target)\n    if distance > .25 then\n        local tip = math.min(1.25, distance)\n        local arrow = TensorCore.getStaticDrawer(GUI:ColorConvertFloat4ToU32(0, 1, 0, .95), 2)\n        arrow:addTimedArrow(duration, player.pos.x, player.pos.y, player.pos.z, arrowHeading, math.max(.15, distance - tip), .9, tip, 1.9, 0, false)\n    end\nend\nself.used = true",
