r = redDirs[1]\nelseif score2 > score1 + 0.0001 then\n    nearDir = redDirs[2]\nelse\n    -- Clockwise travel decreases TensorCore's heading.\n    local clockwise1 = (bossHeading - redHeading1) % (2 * math.pi)\n    local clockwise2 = (bossHeading - redHeading2) % (2 * math.pi)\n    nearDir = clockwise1 <= clockwise2 and redDirs[1] or redDirs[2]\nend\nlocal farDir = nearDir == redDirs[1] and redDirs[2] or redDirs[1]\nlocal isMeleeTank = slot == \"MT\" or slot == \"OT\" or slot == \"T1\" or slot == \"T2\" or slot == \"M1\" or slot == \"M2\"\nlocal mirrorDir = isMeleeTank and nearDir or farDir\nlocal offset = geometry.offsets[spreadSlot]\nif offset == nil then self.used = true; return end\nlocal heading = geometry.north - (mirrorDir - 1) * math.pi / 4\nlocal unit = TensorCore.getPosInDirection(center, heading, 1)\nlocal radialX, radialZ = unit.x - center.x, unit.z - center.z\nlocal tangentX, tangentZ = -radialZ, radialX\nlocal lateralOffset = offset[2]\nif isMeleeTank then\n    -- MT's solo side faces the ranged mirror; OT/M2 occupy the opposite side.\n    -- Reflect the whole near-mirror layout when the far mirror is on the other flank.\n    local farHeading = geometry.north - (farDir - 1) * math.pi / 4\n    local farUnit = TensorCore.getPosInDirection(center, farHeading, 1)\n    local towardFar = (farUnit.x - center.x) * tangentX + (farUnit.z - center.z) * tangentZ\n    if towardFar < 0 then lateralOffset = -lateralOffset end\nend\nlocal mirror = TensorCore.getPosInDirection(center, heading, 20)\nlocal targetX = mirror.x + radialX * offset[1] + tangentX * lateralOffset\nlocal targetZ = mirror.z + radialZ * offset[1] + tangentZ * lateralOffset\nlocal duration = math.floor(a.channelTimeMax * 1000 + 850)\nlocal green = TensorCore.getStaticDrawer(GUI:ColorConvertFloat4ToU32(0, 1, 0, .92), 2)\ngreen:addTimedCircle3D(duration, targetX, .05, targetZ, 0.68677875, 0, 0, 0, false, true, Argus2.RenderFlags.FLAG_RENDER_UI)\nlocal player = TensorCore.mGetPlayer()\nif player ~= nil and player.pos ~= nil then\n    local target = { x = targetX, y = 0, z = targetZ }\n    local arrowHeading = TensorCore.getHeadingToTarget(player.pos, target)\n    local distance = TensorCore.getDistance2d(player.pos, target)\n    if distance > .25 then\n        local tip = math.min(1.25, distance)\n        local arrow = TensorCore.getStaticDrawer(GUI:ColorConvertFloat4ToU32(0, 1, 0, .95), 2)\n        arrow:addTimedArrow(duration, player.pos.x, player.pos.y, player.pos.z, arrowHeading, math.max(.15, distance - tip), .9, tip, 1.9, 0, false)\n    end\nend\ndata.lpduFruRedMirrorDrawn = true\nself.used = true",
