\n        local player=roster.entOf(slot)\n        if player and player.pos then\n            local dx=player.pos.x-eventArgs.castPosX\n            local dz=player.pos.z-eventArgs.castPosZ\n            mine=dx*dx+dz*dz<=16\n        end\n    end\n    if not mine then self.used=true;return end\nelse self.used=true; return end\nstate.puddleMoving=false\n-- Collapse after your own five puddles, or after the first towers resolve.\n-- These are safe stack staging positions from LPDU raidplan step 4.\nlocal north=assignment.north\ndo\n local player=roster.entOf(slot)\n if player==nil or player.pos==nil then return end\n -- Preserve the side actually occupied after the first towers, including north/south swaps.\n north=player.pos.z<100\nend\nlocal x,z=north and 104.5 or 89.5,north and 82.5 or 115.5\nlocal duration=math.max(300,math.floor((352-TensorReactions_CurrentTimer)*1000))\nstate.guide(x,z,duration)\nAnyoneCore.Shotcall(\"Regroup\",true,3,true)\nstate.stackNorth=north\nstate.guided=true\nself.used=true\n",
