							aType = "Lua",
							actionLua = "local timer=TensorReactions_CurrentTimer\nlocal settingsRoot=Settings or (_G and _G.Settings)\nlocal settings=settingsRoot and settingsRoot.FFXIVMINION\nif not settings then return end\nlocal mode=settings.LPDU_FRU_CrystalDamageMode or \"AoE then focus\"\nlocal outer=TensorCore.getEntityGroupList(\"ContentID\",13555) or {}\nlocal side=false\nfor _,e in pairs(outer) do\n if e.alive and e.targetable then side=true;break end\nend\nlocal middle=TensorCore.getEntityGroupList(\"ContentID\",9358) or {}\nlocal big=false\nfor _,e in pairs(middle) do\n if e.alive and e.targetable then big=true;break end\nend\nlocal owned=data.lpduCrystalAOE\nlocal focusActive=side or big or (owned and owned.mode==\"Focus assigned crystal\")\nlocal focus=timer>=418.8 and timer<500 and ((mode==\"Focus assigned crystal\" and focusActive) or (mode==\"AoE then focus\" and timer>=423.6 and side))\nif not focus then\nlocal s=data.lpduCrystalAOE\nif s then\n if timer>=500 and s.mode==\"Focus assigned crystal\" then _G[s.var]=true\n elseif _G[s.var]==false then _G[s.var]=s.previous end\n data.lpduCrystalAOE=nil\nend\n self.used=true return\nend\nif not data.lpduCrystalAOE then\n local toggles=TensorCore.API.TensorACR.getQuickToggles()\n if not toggles then return end\n for _,toggle in ipairs(toggles) do\n  if string.match(toggle.var,\"_AOE$\") and type(_G[toggle.var])==\"boolean\" then\n   data.lpduCrystalAOE={var=toggle.var,previous=_G[toggle.var],mode=mode}\n   break\n  end\n end\nend\nlocal s=data.lpduCrystalAOE\nif s then\n if big then s.bigSeen=true end\n _G[s.var]=false\nend\nself.used=true\n",
