						data = 
						{
							aType = "Lua",
							actionLua = "local settings=Settings.FFXIVMINION\nlocal roster=AnyoneCore.Roster\nif not roster or roster.current()==nil or not roster.isReady() then self.used=true;return end\nlocal p=TensorCore.mGetPlayer()\nif not p or not p.pos then self.used=true;return end\nlocal state=data.lpduCrystalTarget\nif not state then state={};data.lpduCrystalTarget=state end\nif state.done then self.used=true;return end\nif not state.position then\n local markBySlot={T1=1,R1=1,H1=4,M1=4,T2=2,R2=2,H2=3,M2=3}\n local mark=markBySlot[roster.mySlot()]\n if not mark then self.used=true;return end\n local x,y,z,active=Argus.getWaymarkInfo(mark)\n if not active then x,y,z,active=Argus.getWaymarkInfo(mark+4) end\n if not active then self.used=true;return end\n -- Confirmed outer spawn coordinates; select the one nearest the pair's color.\n local spots={{x=100,y=0,z=85},{x=115,y=0,z=100},{x=100,y=0,z=115},{x=85,y=0,z=100}}\n local closest,best\n for _,spot in ipairs(spots) do\n  local d=(spot.x-x)^2+(spot.z-z)^2\n  if not best or d<best then closest=spot;best=d end\n end\n state.position=closest\nend\nlocal outer=TensorCore.getEntityGroupList(\"ContentID\",13555) or {}\nlocal mine,held,nextOuter,best\nfor _,e in pairs(outer) do\n if e.pos and e.alive and e.targetable then\n  local distance=TensorCore.getDistance2d(e.pos,state.position)\n  if distance<1 then mine=e end\n  if e.id==state.target then held=e end\n  local d=TensorCore.getDistance2d(p.pos,e.pos)\n  if not best or d<best or (d==best and e.id<nextOuter.id) then nextOuter=e;best=d end\n end\nend\n-- Always own first. After it breaks, hold one other live outer crystal at a time.\nlocal target\nif not state.ownDone then\n if mine then target=mine;state.ownSeen=true\n elseif state.ownSeen then state.ownDone=true end\nend\nif state.ownDone then target=held or nextOuter end\nif not target and state.ownDone and not nextOuter then\n local middle=TensorCore.getEntityGroupList(\"ContentID\",9358) or {}\n for _,e in pairs(middle) do if e.alive and e.targetable then target=e;break end end\n if target then state.middleSeen=true\n elseif state.middleSeen then state.done=true end\nend\nif target then\n state.target=target.id\n if p.targetid~=target.id then Player:SetTarget(target.id) end\nend\nself.used=true\n",
