l buff = TensorCore.getBuff(ent, buffid)\n        --d(buff)\n\n        if playerBuff and buff then\n            if math.abs(buff.duration - playerBuff.duration) < 1 then\n                local iPos = 999\n                for pos, val in ipairs(customOrder) do\n                    if val == i then\n                        iPos = pos\n                        break\n                    end\n                end\n                if idxPos < iPos then\n                    return true\n                else\n                    return false\n                end\n            end\n        end\n    end\n\n    return false\nend\n\n\nlocal green = TensorCore.getStaticDrawer(GUI:ColorConvertFloat4ToU32(0/255, 255/255, 0/255, .25),2)\ndata.lpdu_fru_ur_centers={}\ndata.lpdu_fru_ur_outs={}\nlocal function personalArrow(timeout,x,y,z,heading,length,width,tip,tipWidth,delay,progressive)\n if length<17 then\n  local start=TensorReactions_CurrentTimer+(delay or 0)/1000\n  local text=length<=3 and \"Stack middle\" or (length<8 and \"Spread\" or \"Bait laser\")\n  local rewind=length==2 or length==7.5\n  local reach=length+(tip or 0)\n  table.insert(data.lpdu_fru_ur_outs,{start=start,finish=start+timeout/1000,text=text,rewind=rewind,\n   x=x+math.sin(heading)*reach,z=z+math.cos(heading)*reach})\n end\n if length>=17 then\n  local start=TensorReactions_CurrentTimer+(delay or 0)/1000\n  table.insert(data.lpdu_fru_ur_outs,{start=start,finish=start+timeout/1000})\n end\n return green:addTimedArrow(timeout,x,y,z,heading,length,width,tip,tipWidth,delay,progressive)\nend\nlocal function centerCircle(timeout,x,y,z,radius,delay,progressive)\n local start=TensorReactions_CurrentTimer+(delay or 0)/1000\n table.insert(data.lpdu_fru_ur_centers,{start=start,finish=start+timeout/1000})\n return green:addTimedCircle(timeout,x,y,z,radius,delay,progressive)\nend\nlocal center = {x = 100, y = 0,z = 100}\nlocal fire = 2455\nlocal ice = 2462\nlocal yellow = 2454\nlocal water = 2461\nlocal dark = 2460\nlocal heading2North = data.megaminx_p3_ur_north\nif TensorCore.isTank(p) or TensorCore.isHealer(p) then --support\n    if TensorCore.hasBuff(p,fire,nil,nil,20) then --long fire\n        --center, ne nw bait, center ice, center(rewind), out, center\n\n        local result = checkDebuff(index, 1, 4, fire)\n        if (result == true) then\n            AnyoneCore.Shotcall(\"left\", true, 40, false)\n        else\n            AnyoneCore.Shotcall(\"right\", true, 40, false)\n        end\n\n        local sideHeading = heading2North + (result and math.pi/4 or -math.pi/4)\n        local duration = buffs[2455] * 1000\n\n\n        centerCircle(duration  - 20000,center.x,0,center.z,5,0,true) --center\n\n        personalArrow(5000, 100, 0, 100, sideHeading, 8.5, 1, 1, 1,duration  - 20000,true) --\n\n        centerCircle(5000,center.x,0,center.z,3,duration  - 20000 + 5000,true) --center ice\n\n        personalArrow(5000, 100, 0, 100, sideHeading, 2, 1, 1, 1,duration  - 20000 + 5000 + 5000,true) --\n\n        personalArrow(5000, 100, 0, 100, sideHeading, 18, 1, 1, 1,duration  - 20000 + 5000 + 5000 + 5000,true) --\n\n        centerCircle(5000,center.x,0,center.z,5,duration  - 20000 + 5000 + 5000 + 5000 + 5000,true) --center\n    elseif TensorCore.hasBuff(p,fire,nil,nil,10) then --medium fire\n        --center, rewind(dark out water in), out(west (9east)), center, center, bait(west (9east))\n        local duration = buffs[2455] * 1000\n\n\n        centerCircle(duration  - 10000,center.x,0,center.z,5,0,true) --center\n\n        if TensorCore.hasBuff(p,water) then\n            personalArrow(5000, 100, 0, 100, heading2North + math.pi/2, 2, 1, 1, 1,duration  - 10000,true) --rewind\n        end\n        if TensorCore.hasBuff(p,dark) then\n            personalArrow(5000, 100, 0, 100, heading2North + math.pi/2, 7.5, 1, 1, 1,duration  - 10000,true) --rewind\n        end--\n\n        personalArrow(5000, 100, 0, 100, heading2North + math.pi/2, 18, 1, 1, 1,duration  - 10000 + 5000,true) --out\n        \n\n        centerCircle(5000,center.x,0,center.z,5,duration  - 10000 + 5000 + 5000,true) --center\n\n        centerCircle(5000,center.x,0,center.z,5,duration  - 10000 + 5000 + 5000 + 5000,true) --center\n\n        personalArrow(5000, 100, 0, 100, heading2North + math.pi/2, 8.5, 1, 1, 1,duration  - 10000 + 5000 + 5000 + 5000 + 5000,true) --bait hourglass\n    else -- short fire or ice\n        --(ice center, fire out), rewind(dark out water in), center ice, n bait, center, center\n        local duration\n        local isIce = TensorCore.hasBuff(p,ice)\n        local isFire = TensorCore.hasBuff(p,fire)\n        if isIce then\n            duration = buffs[2462] * 1000 - 10000\n            centerCircle(duration,center.x,0,center.z,5,0,true) --center if ice\n        end\n        if isFire then\n            duration = buffs[2455] * 1000\n            personalArrow(duration, 100, 0, 100, heading2North , 18, 1, 1, 1,0,true) --out if fire\n        end\n\n        if TensorCore.hasBuff(p,water) then\n            personalArrow(5000, 100, 0, 100, heading2North, 2, 1, 1, 1,duration,true) --rewind\n        end\n        if TensorCore.hasBuff(p,dark) then\n            personalArrow(5000, 100, 0, 100, heading2North, 7.5, 1, 1, 1,duration,true) --rewind\n        end\n\n        centerCircle(5000,center.x,0,center.z,3,duration + 5000,true) --center ice\n\n        personalArrow(5000, 100, 0, 100, heading2North, 8.5, 1, 1, 1,duration + 5000 + 5000,true) --bait hourglass\n\n        centerCircle(5000,center.x,0,center.z,5,duration + 5000 + 5000 + 5000,true) --center\n\n        centerCircle(5000,center.x,0,center.z,5,duration + 5000 + 5000 + 5000 + 5000,true) --center\n    end\nelse --dps\n\n    if TensorCore.hasBuff(p,fire,nil,nil,20) or TensorCore.hasBuff(p,ice) then --long fire\n        --center, s bait, center ice, center(rewind), out, center\n        local duration\n        local isIce = TensorCore.hasBuff(p,ice)\n        local isFire = TensorCore.hasBuff(p,fire)\n        if isIce then\n            duration = buffs[2462] * 1000 + 10000\n        end\n        if isFire then\n            duration = buffs[2455] * 1000\n        end\n\n\n        centerCircle(duration  - 20000,center.x,0,center.z,5,0,true) --center\n\n        personalArrow(5000, 100, 0, 100, heading2North + math.pi, 8.5, 1, 1, 1,duration  - 20000,true) --bait hourglass\n\n        centerCircle(5000,center.x,0,center.z,3,duration  - 20000 + 5000,true) --center ice\n\n        personalArrow(5000, 100, 0, 100, heading2North + math.pi, 2, 1, 1, 1,duration  - 20000 + 5000 + 5000,true) --rewind\n\n        personalArrow(5000, 100, 0, 100, heading2North + math.pi, 18, 1, 1, 1,duration  - 20000 + 5000 + 5000 + 5000,true) --out\n\n        centerCircle(5000,center.x,0,center.z,5,duration  - 20000 + 5000 + 5000 + 5000 + 5000,true) --center\n    elseif TensorCore.hasBuff(p,fire,nil,nil,10) then --medium fire\n        --center, rewind(dark out water in), out(east (9west)), center, center, bait(east (9west))\n        --center, rewind(dark out water in), out(west (9east)), center, center, bait(west (9east))\n        local duration = buffs[2455] * 1000\n\n\n        centerCircle(duration  - 10000,center.x,0,center.z,5,0,true) --center\n\n        if TensorCore.hasBuff(p,water) then\n            personalArrow(5000, 100, 0, 100, heading2North - math.pi/2, 2, 1, 1, 1,duration  - 10000,true) --rewind\n        end\n        if TensorCore.hasBuff(p,dark) then\n            personalArrow(5000, 100, 0, 100, heading2North - math.pi/2, 7.5, 1, 1, 1,duration  - 10000,true) --rewind\n        end--\n\n        personalArrow(5000, 100, 0, 100, heading2North - math.pi/2, 18, 1, 1, 1,duration  - 10000 + 5000,true) --out\n        \n\n        centerCircle(5000,center.x,0,center.z,5,duration  - 10000 + 5000 + 5000,true) --center\n\n        centerCircle(5000,center.x,0,center.z,5,duration  - 10000 + 5000 + 5000 + 5000,true) --center\n\n        personalArrow(5000, 100, 0, 100, heading2North - math.pi/2, 8.5, 1, 1, 1,duration  - 10000 + 5000 + 5000 + 5000 + 5000,true) --bait hourglass\n    else -- short fire or ice\n        --fire out se sw, rewind(dark out water in), center, sw se bait, center, center\n        --(ice center, fire out), rewind(dark out water in), center ice, n bait, center, center\n        local duration = buffs[2455] * 1000\n\n        local result = checkDebuff(index, 5, 8, fire)\n        if (result == true) then\n            AnyoneCore.Shotcall(\"left\", true, 40, false)\n        else\n            AnyoneCore.Shotcall(\"right\", true, 40, false)\n        end\n\n        local sideHeading = heading2North + (result and 3*math.pi/4 or -3*math.pi/4)\n\n        personalArrow(duration, 100, 0, 100, sideHeading , 18, 1, 1, 1,0,true) --out if fire\n\n        if TensorCore.hasBuff(p,water) then\n            personalArrow(5000, 100, 0, 100, sideHeading, 2, 1, 1, 1,duration,true) --rewind\n        end\n        if TensorCore.hasBuff(p,dark) then\n            personalArrow(5000, 100, 0, 100, sideHeading, 7.5, 1, 1, 1,duration,true) --rewind\n        end\n\n        centerCircle(5000,center.x,0,center.z,3,duration + 5000,true) --center ice\n\n        personalArrow(5000, 100, 0, 100, sideHeading, 8.5, 1, 1, 1,duration + 5000 + 5000,true) --bait hourglass\n\n        centerCircle(5000,center.x,0,center.z,5,duration + 5000 + 5000 + 5000,true) --center\n\n        centerCircle(5000,center.x,0,center.z,5,duration + 5000 + 5000 + 5000 + 5000,true) --center\n    end\nend\nself.used = true",
