far-bait tank and changes its guidance arrow. With Invuln both hits, this tank takes both hits; with Tank swap, the other tank takes the close hit. This does not change P5 invuln order.\",\n LPDU_FRU_P5FirstInvuln=\"Selects the invuln tank for the first P5 Wings set; the other tank invulns the second set. Changes invuln/bait versus cleave guidance and LPDU mitigation assignments. PLD cooldown restrictions may reject the plan when LPDU mits is active/inherited.\"\n}\nlocal function optionTooltip(key)\n if GUI:IsItemHovered() then GUI:SetTooltip(optionHelp[key]) end\nend\nlocal function tankChoice(label,key,default)\n local value=settings[key] or default\n GUI:Text(label);GUI:SameLine(190);GUI:PushItemWidth(150)\n local i=GUI:Combo(\"##\"..key,value==\"MT\" and 1 or 2,{\"MT\",\"OT\"})\n optionTooltip(key)\n GUI:PopItemWidth()\n local chosen=i==1 and \"MT\" or \"OT\"\n settings[key]=chosen;return chosen\nend\nlocal visible=GUI:Begin(\"[LPDU] FRU - Settings\",true,GUI.WindowFlags_AlwaysAutoResize)\nif visible then\n local function akhChoice(label,key,default)\n  local modes={\"4-4\",\"7-1 MT solo\",\"7-1 OT solo\"}\n  local value=settings[key] or default\n  GUI:Text(label);GUI:SameLine(190);GUI:PushItemWidth(150)\n  local i=GUI:Combo(\"##\"..key,value==modes[2] and 2 or (value==modes[3] and 3 or 1),modes)\n  optionTooltip(key)\n  GUI:PopItemWidth();settings[key]=modes[i]\n end\n if GUI:CollapsingHeader(\"P1##LPDUFRUP1\") then\n local choices={\"Disabled\",\"Enabled\"}\n local choice=GUI:Combo(\"Swap DPS spreads\",settings.LPDU_FRU_P1SwapRangedSpreads==\"Enabled\" and 2 or 1,choices)\n settings.LPDU_FRU_P1SwapRangedSpreads=choices[choice] or \"Disabled\"\n if GUI:IsItemHovered() then GUI:SetTooltip(\"Off by default. Exchanges M1 with R1 and M2 with R2 only for the P1 safe-side spread after the clones (around 47 seconds). Clock spots, other Proteans, stacks, tethers and towers stay unchanged. Match your party's spread plan.\") end\n end\n if settings.LPDU_FRU_MirrorOrder==nil then settings.LPDU_FRU_MirrorOrder=\"TDDT\" end\n if GUI:CollapsingHeader(\"P2##LPDUFRUP2\") then\n local mirrorModes={\"TDDT\",\"DTTD\"}\n local mirrorIndex=settings.LPDU_FRU_MirrorOrder==\"DTTD\" and 2 or 1\n local nextMirror=GUI:Combo(\"Mirror spread order\",mirrorIndex,mirrorModes)\n if mirrorModes[nextMirror] then settings.LPDU_FRU_MirrorOrder=mirrorModes[nextMirror] end\n if GUI:IsItemHovered() then GUI:SetTooltip(\"TDDT is the LPDU default: tanks outside, melees inside. DTTD swaps each tank with its same-group melee for blue and red mirror protean positions. Healer/ranged positions and mirror group assignments do not change. Match your party's chosen order.\") end\n GUI:Text(\"Mirrors: TDDT is the LPDU default. Match the party's order.\")\n GUI:Separator()\n GUI:Text(\"Intermission crystals\")\n local targetModes={\"Disabled\",\"Enabled\"}\n local targetIndex=GUI:Combo(\"Auto-target crystals\",settings.LPDU_FRU_CrystalTargetMode==\"Enabled\" and 2 or 1,targetModes)\n settings.LPDU_FRU_CrystalTargetMode=targetModes[targetIndex] or \"Disabled\"\n if GUI:IsItemHovered() then GUI:SetTooltip(\"Disabled by default. Focus the light crystal in your color coded pair.\\nYour crystal > another remaining outer light crystal > middle Ice Veil. Keeps each target until it breaks.\\nUses your assigned roster role and the matching A/B/C/D color waymark (or 1/2/3/4 if its letter is absent). Requires that color marker to be active.\") end\n GUI:Text(\"Focus the light crystal in your color coded pair.\")\n GUI:Text(\"MT + R1: Red    H1 + M1: Purple\")\n GUI:Text(\"OT + R2: Yellow    H2 + M2: Blue\")\n local modes={\"ACR default\",\"Focus assigned crystal\",\"AoE then focus\"}\n local selected=settings.LPDU_FRU_CrystalDamageMode or \"AoE then focus\"\n local index=3\n for i,value in ipairs(modes) do if value==selected then index=i break end end\n local nextIndex=GUI:Combo(\"P2 crystal damage\",index,modes)\n if modes[nextIndex] then settings.LPDU_FRU_CrystalDamageMode=modes[nextIndex] end\n if GUI:IsItemHovered() then GUI:SetTooltip(\"ACR default: no rotation override.\\nFocus assigned crystal: suppress AoE while a side Crystal of Light is targeted.\\nAoE then focus: allow early cleave; suppress AoE after the first Blizzard at synced timeline 423.6s (~4.8s after targetable).\\nTargeting is controlled separately by Auto-target crystals. AoE then focus holds AoE off after 4.8 seconds until P3 starts; wipes restore the previous setting.\\nThe cutoff is a conservative strategy choice, not a measured per-job DPS optimum.\") end\n end\n if GUI:CollapsingHeader(\"P3##LPDUFRUP3\") then\n local urModes={\"Disabled\",\"Enabled\"}\n local urIndex=GUI:Combo(\"UR rewind guidance\",(settings.LPDU_FRU_URRewindGuidance or \"Enabled\")==\"Enabled\" and 2 or 1,urModes)\n settings.LPDU_FRU_URRewindGuidance=urModes[urIndex] or \"Enabled\"\n if GUI:IsItemHovered() then GUI:SetTooltip(\"Enabled by default. Adds a green circle at your personal rewind-recording destination and says Place rewind when that step begins. Uses the existing UR debuff assignment and arrow. The circle expires when that step ends. The existing rewind countdown is unchanged.\") end\n if isTank then\n tankChoice(\"P3 Halo tank\",\"LPDU_FRU_HaloTank\",\"MT\")\n tankChoice(\"P3 Apoc bait\",\"LPDU_FRU_ApocBait\",\"OT\")\n  GUI:Text(\"Halo takes Black Halo; Apoc baits Darkest Dance.\")\n  if data.lpdu_fru_gnb_v3_defaults and job==37 then GUI:Text(\"GNB V3 defaults: MT Halo; OT Apoc.\") end\n end -- P3 tank choices\n end -- P3\n if isTank then\n if GUI:CollapsingHeader(\"P4##LPDUFRUP4\") then\n akhChoice(\"P4 Akh Morn 1\",\"LPDU_FRU_P4AM1Mode\",\"4-4\")\n akhChoice(\"P4 Akh Morn 2\",\"LPDU_FRU_P4AM2Mode\",\"7-1 MT solo\")\n if data.lpdu_fru_gnb_v3_defaults and TensorCore.mGetPlayer().job==37 then\n  GUI:Text(\"GNB V3 default: MT takes both Somber hits.\")\n  GUI:Text(\"Match the GNB ACR MT/OT role to the party roster.\")\n elseif replayDefaults then\n  GUI:Text(\"DRK/PLD defaults: first PLD solo; second DRK solo.\")\n else\n  GUI:Text(\"LPDU Mitsheet default: first 4-4; second MT solo / party with OT.\")\n end\n GUI:Text(\"Both tanks and party must agree on the grouping.\")\n bait=tankChoice(\"P4 far bait\",\"LPDU_FRU_P4Bait\",bait)\n GUI:Text(\"P4 tank plan\");GUI:SameLine(190);GUI:PushItemWidth(150)\n local plan=GUI:Combo(\"##LPDUFRUP4Plan\",mode==\"Tank swap\" and 2 or 1,{\"Invuln both hits\",\"Tank swap\"})\n if GUI:IsItemHovered() then GUI:SetTooltip(\"Changes P4 Somber Dance tank instructions and LPDU mitigation assignments. Invuln both hits uses the far-bait tank for both hits. Tank swap splits the hits; active/inherited LPDU mits requires first Akh Morn to use 4-4. Other choices remain available without LPDU mits.\") end\n GUI:PopItemWidth()\n settings.LPDU_FRU_DarklitTank=plan==2 and \"Tank swap\" or bait..\" invulns\"\n GUI:Text(plan==2 and (bait..\" far / other tank close\") or (bait..\" takes both hits\"))\n end\n if GUI:CollapsingHeader(\"P5##LPDUFRUP5\") then\n local first=tankChoice(\"P5 first invuln\",\"LPDU_FRU_P5FirstInvuln\",\"MT\")\n GUI:Text(\"P5: \"..first..\" first / \"..(first==\"MT\" and \"OT\" or \"MT\")..\" second\")\n GUI:Text(\"Confirm these assignments with your co-tank.\")\n GUI:Text(\"Both tanks must match settings.\")\n  if data.lpdu_fru_gnb_v3_defaults and job==37 then GUI:Text(\"GNB V3 default: OT invulns first.\") end\n end\n end -- tank-only phase controls\n local planKeys={\"LPDU_FRU_P4AM1Mode\",\"LPDU_FRU_P4AM2Mode\",\"LPDU_FRU_HaloTank\",\"LPDU_FRU_ApocBait\",\"LPDU_FRU_P4Bait\",\"LPDU_FRU_DarklitTank\",\"LPDU_FRU_P5FirstInvuln\",\"LPDU_FRU_CrystalDamageMode\",\"LPDU_FRU_MirrorOrder\",\"LPDU_FRU_CrystalTargetMode\",\"LPDU_FRU_URRewindGuidance\",\"LPDU_FRU_P1SwapRangedSpreads\"}\n local defaults={\"4-4\",\"7-1 MT solo\",\"MT\",\"OT\",bait,mode,\"MT\",\"AoE then focus\",\"TDDT\",\"Disabled\",\"Enabled\",\"Disabled\"}\n local function snapshot()\n  local result={}\n  for i,key in ipairs(planKeys) do\n   local value=settings[key]\n   result[key]=value~=nil and value or defaults[i]\n  end\n  return result\n end\n if GUI:Button(\"Save settings\") then\n  settings.LPDU_FRU_SavedSettings=snapshot()\n  data.lpdu_plan_message=\"All FRU settings saved.\"\n end\n if GUI:IsItemHovered() then GUI:SetTooltip(\"Save all FRU options, including crystal damage, mirror spread order and tank assignments.\") end\n if GUI:CollapsingHeader(\"Settings backup / sharing\") then\n  if GUI:Button(\"Export to clipboard\") then\n   local values=snapshot()\n   local lines={\"LPDU-FRU-SETTINGS-v2\"}\n   for _,key in ipairs(planKeys) do table.insert(lines,key..\"=\"..values[key]) end\n   GUI:SetClipboardText(table.concat(lines,\"\\n\"))\n   data.lpdu_plan_message=\"All FRU settings copied to clipboard.\"\n  end\n  GUI:SameLine()\n  if GUI:Button(\"Import from clipboard\") then\n   local text=GUI:GetClipboardText() or \"\"\n   local values={};local count=0;local valid=true\n   local allowed={}\n   for i,key in ipairs(planKeys) do allowed[key]=i end\n   local first=true;local legacy=false\n   for line in string.gmatch(text,\"[^\\r\\n]+\") do\n    if first then\n     legacy=line==\"LPDU-FRU-TANK-v1\"\n     valid=legacy or line==\"LPDU-FRU-SETTINGS-v2\";first=false\n    else\n     local key,value=string.match(line,\"^([%w_]+)=(.+)$\")\n     local i=key and allowed[key]\n     local ok=i~=nil and values[key]==nil and (not legacy or i<=7)\n     if ok and i<=2 then\n      ok=value==\"4-4\" or value==\"7-1 MT solo\" or value==\"7-1 OT solo\"\n     elseif ok and i==6 then\n      ok=value==\"MT invulns\" or value==\"OT invulns\" or value==\"Tank swap\"\n     elseif ok and i==8 then\n      ok=value==\"ACR default\" or value==\"Focus assigned crystal\" or value==\"AoE then focus\"\n     elseif ok and i==9 then\n      ok=value==\"TDDT\" or value==\"DTTD\"\n     elseif ok and (i==10 or i==11 or i==12) then\n      ok=value==\"Disabled\" or value==\"Enabled\"\n     elseif ok then ok=value==\"MT\" or value==\"OT\" end\n     if not ok then valid=false else values[key]=value;count=count+1 end\n    end\n   end\n   if valid and ((legacy and count==7) or (not legacy and (count==9 or count==10 or count==11 or count==#planKeys))) then\n    data.lpdu_plan_import=values\n    data.lpdu_plan_message=legacy and \"Legacy tank plan: P2 options stay unchanged. Review, then Apply.\" or \"Review all imported FRU settings, then Apply.\"\n   else data.lpdu_plan_import=nil;data.lpdu_plan_message=\"Invalid or incomplete FRU settings.\" end\n  end\n  if data.lpdu_plan_import then\n   for _,key in ipairs(planKeys) do\n    local value=data.lpdu_plan_import[key]\n    if value~=nil then GUI:Text(string.gsub(key,\"LPDU_FRU_\",\"\")..\": \"..value) end\n   end\n   if GUI:Button(\"Apply import\") then\n    for _,key in ipairs(planKeys) do\n     local value=data.lpdu_plan_import[key]\n     if value~=nil then settings[key]=value end\n    end\n    data.lpdu_plan_import=nil\n    data.lpdu_plan_message=\"Imported FRU settings applied.\"\n   end\n   GUI:SameLine()\n   if GUI:Button(\"Cancel import\") then data.lpdu_plan_import=nil end\n  end\n  local saved=settings.LPDU_FRU_SavedSettings or settings.LPDU_FRU_SavedTankPlan\n  if saved then\n   local loadSaved=GUI:Button(\"Load saved settings\")\n   if GUI:IsItemHovered() then GUI:SetTooltip(\"Load your saved FRU options. Older tank-only saves leave P2 crystal and mirror options unchanged.\") end\n   if loadSaved then\n    for _,key in ipairs(planKeys) do\n     local value=saved[key]\n     if value~=nil then settings[key]=value end\n    end\n    data.lpdu_plan_message=\"Saved settings loaded.\"\n   end\n  end\n end\n if data.lpdu_plan_message then GUI:Text(data.lpdu_plan_message) end\nend\nGUI:End();self.used=true\n",
